import{_ as a,o as l,c as i,a2 as o}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"市場系統","description":"提供玩家一個公開交易市場，供玩家們購買與收購相關物品。","frontmatter":{"title":"市場系統","description":"提供玩家一個公開交易市場，供玩家們購買與收購相關物品。"},"headers":[],"relativePath":"feature/market/index.md","filePath":"feature/market.md"}'),t={name:"feature/market/index.md"};function r(d,e,c,h,b,s){return l(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="市場系統" tabindex="-1">市場系統 <a class="header-anchor" href="#市場系統" aria-label="Permalink to &quot;市場系統&quot;">​</a></h1><p>本伺服原創與自行開發的市場系統，提供玩家一個公開交易市場</p><h2 id="使用方式" tabindex="-1">使用方式 <a class="header-anchor" href="#使用方式" aria-label="Permalink to &quot;使用方式&quot;">​</a></h2><p>輸入<code>/bs</code>點擊綠寶石開啟市場介面<br><img src="https://i.imgur.com/cLSx2fX.png" style="width:40%;"></p><h2 id="市場使用說明" tabindex="-1">市場使用說明 <a class="header-anchor" href="#市場使用說明" aria-label="Permalink to &quot;市場使用說明&quot;">​</a></h2><h3 id="圖片說明" tabindex="-1">圖片說明 <a class="header-anchor" href="#圖片說明" aria-label="Permalink to &quot;圖片說明&quot;">​</a></h3><img src="https://i.imgur.com/iWtXBMe.png"><h3 id="市場資訊說明" tabindex="-1">市場資訊說明 <a class="header-anchor" href="#市場資訊說明" aria-label="Permalink to &quot;市場資訊說明&quot;">​</a></h3><img src="https://i.imgur.com/cZZS21V.png" style="width:45%;"><p><b>市場資訊：</b>該品項在市場上的基本資訊<br><b>單位數量：</b>每交易一個單位所代表的物品數量<br><b>價格區間：</b>上架收購/販售單時允許設定的價格區間<br><b>販售倉量：</b>目前市場上有多少物品正在販售，其中個人及全伺服有個別的上限<br><b>目前收購市價：</b>目前將每單位物品賣給收購市場會獲得的金錢，也是目前收購單中最高的價錢<br><b>目前販售市價：</b>目前從販售市場購買每單位物品會獲得的金錢，也是目前販售單中最低的價錢<br><b>七日交易資訊：</b>過去七天該品項在市場上的交易狀況，可用以判斷市場當前的熱度及行情<br><b>總成交量：</b>該品項在收購市場及販售市場上的總成交量<br><b>成交價格區間：</b>該品項在收購市場及販售市場上成交的價格區間<br><b>平均成交價格：</b>該品項在收購市場及販售市場上的平均成交價格</p><h3 id="判斷熱度及行情" tabindex="-1">判斷熱度及行情 <a class="header-anchor" href="#判斷熱度及行情" aria-label="Permalink to &quot;判斷熱度及行情&quot;">​</a></h3><h4 id="市場熱度" tabindex="-1">市場熱度： <a class="header-anchor" href="#市場熱度" aria-label="Permalink to &quot;市場熱度：&quot;">​</a></h4><p>可從七日總成交量得知目前指定物品的交易熱度，越高代表參與買賣的人越多。<br> 而熱度越高不一定代表能更快從販售/收購中得到收益，要同時參考販售倉量，倉量越高通常越慢。<br> 如果想要從市場上得到更多的收益，可以試著考慮交易熱度相對低一些，但販售價格也不差的商品。</p><h4 id="行情價" tabindex="-1">行情價： <a class="header-anchor" href="#行情價" aria-label="Permalink to &quot;行情價：&quot;">​</a></h4><p>最直接的方法是參考七日平均成交價格，將它當作目前的市場行情價。<br> 而為了得到更具參考性的資訊，通常我們會加上總成交量以及成交價格區間綜合評估，這需要一點統計的概念。 有時候也可以參考玩家在商店街或是私下販售的價格，這可能會比市場熱度極差時的平均成交價格值得參考。</p><h3 id="購買商品的優先順序" tabindex="-1">購買商品的優先順序 <a class="header-anchor" href="#購買商品的優先順序" aria-label="Permalink to &quot;購買商品的優先順序&quot;">​</a></h3><ul><li>先買最低價格的商品(由最低價往上購買) <ul><li>想更快賣掉商品得到收益的話可以適度地降低販售價格，幅度越大通常越快</li></ul></li><li>相同價格則以最久的上架時間來購買(先進先出)</li></ul><h3 id="販售商品的優先順序" tabindex="-1">販售商品的優先順序 <a class="header-anchor" href="#販售商品的優先順序" aria-label="Permalink to &quot;販售商品的優先順序&quot;">​</a></h3><ul><li>先賣最高價格的商品(由最高價往下購買) <ul><li>想更快買到商品的話可以適度地提高收購價格，幅度越大通常越快</li></ul></li><li>相同價格則以最久的上架時間來購買(先進先出)</li></ul><h2 id="收購單上架" tabindex="-1">收購單上架 <a class="header-anchor" href="#收購單上架" aria-label="Permalink to &quot;收購單上架&quot;">​</a></h2><ul><li>上架方式 : 輸入<code>/buy &lt;市場名稱&gt; &lt;你想要收購的每單位價格&gt; &lt;單位&gt;</code><ul><li>EX: 假設你想收<code>30單位</code>沙子 你希望每單位收<code>5.0元</code></li><li>輸入<code>/buy sand 5.0 30</code></li></ul></li><li>上架需先支付保證金! (收購單不收上架費用) <ul><li>EX: 收購 沙子<code>5.0元</code>x<code>30單位</code>保證金150元</li></ul></li><li>若要撤銷收購單，請點至沙子的商品頁面，並點擊綠色界伏盒來撤銷收購單(會退還你剩餘的保證金) <ul><li>撤銷收購單需另外從退還的保證金扣除2%撤銷手續費 最低<code>0.1元</code></li><li>上架滿72小時後才能撤銷</li></ul></li><li><code>/purchaseshelf t</code><b>查看你目前收購的物品</b></li></ul><h2 id="販售單上架" tabindex="-1">販售單上架 <a class="header-anchor" href="#販售單上架" aria-label="Permalink to &quot;販售單上架&quot;">​</a></h2><ul><li>上架方式 : 輸入<code>/sell &lt;市場名稱&gt; &lt;你想要販售的每單位價格&gt; &lt;單位&gt;</code><ul><li>EX: 假設你身上有<code>30單位</code>白色羊毛 你希望賣每單位<code>5元</code></li><li>輸入<code>/sell white_wool 5.0 30</code></li></ul></li><li>上架有手續費!每單會先向你收<code>2%</code>的上架費用 最低<code>0.1元</code><ul><li>EX: 上架 白色羊毛<code>3.0元</code>x<code>20單位</code>上架手續費為<code>1.2元</code></li><li>EX: 上架 白色羊毛<code>2.0元</code>x<code>1單位</code>上架手續費為<code>0.1元</code></li></ul></li><li>若要撤銷販售單，請點至商品頁面，並點擊紅色界伏盒來撤銷販售單(會退還你剩餘商品) <ul><li>撤銷販售單需另外支付2%撤銷手續費</li><li>上架滿72小時後才能撤銷</li></ul></li><li><code>/sellshelf t</code><b>查看你目前販售的物品</b></li></ul><h2 id="領取販售單收益" tabindex="-1">領取販售單收益 <a class="header-anchor" href="#領取販售單收益" aria-label="Permalink to &quot;領取販售單收益&quot;">​</a></h2><p>登入時如果有販售單有賣出東西收益 會跳通知告訴你<br> 賣家輸入<code>/sellreceive</code>即可領錢</p><h2 id="領取收購單貨物" tabindex="-1">領取收購單貨物 <a class="header-anchor" href="#領取收購單貨物" aria-label="Permalink to &quot;領取收購單貨物&quot;">​</a></h2><p>登入時如果收購單有收到東西 會跳通知告訴你<br> 買家輸入<code>/stock</code>即可領取收購到的商品</p><h2 id="市場賺錢方式" tabindex="-1">市場賺錢方式 <a class="header-anchor" href="#市場賺錢方式" aria-label="Permalink to &quot;市場賺錢方式&quot;">​</a></h2><img src="https://i.imgur.com/8zBxdsE.png" style="width:100%;">',29)])])}const m=a(t,[["render",r]]);export{u as __pageData,m as default};
